package com.cpgame.batchd.treasurehunt.api;

import com.cpgame.batchd.treasurehunt.core.GameRuleCore;import java.math.BigDecimal;import java.util.ArrayList;import java.util.LinkedHashMap;import java.util.List;import java.util.Map;

final class ProviderPresenter{private ProviderPresenter(){}static Prepared prepare(GameRuleCore.CompleteRound round,BigDecimal bet,int level){var ev=GameRuleCore.evaluate(round);BigDecimal betGold=GameRuleCore.paidBet(bet,level),total=GameRuleCore.totalWin(bet,level,ev.totalUnits());List<Map<String,Object>>props=new ArrayList<>();for(int i=0;i<round.steps().size();i++){var step=round.steps().get(i);var se=ev.steps().get(i);List<Map<String,Object>>wins=new ArrayList<>();for(var w:se.wins())wins.add(Map.of("line",w.line(),"odd",w.odd(),"tw",GameRuleCore.totalWin(bet,level,w.odd()),"wp",w.wp()));Map<String,Object>p=new LinkedHashMap<>();p.put("all",se.factor()==10?1:0);p.put("prop",ints(step.symbols()));p.put("tw",GameRuleCore.totalWin(bet,level,se.stepUnits()));p.put("win_arr",wins);props.add(p);}Map<String,Object>detail=new LinkedHashMap<>();detail.put("bet",bet);detail.put("bet_gold",betGold);detail.put("level",level);detail.put("odds",GameRuleCore.displayedOdds(ev.totalUnits()));detail.put("props",props);detail.put("result",props);Map<String,Object>step=new LinkedHashMap<>();step.put("props",props);step.put("result",props);step.put("bet",false);step.put("extend",Map.of("act_bet_gold",0,"act_id","0","act_type",0));detail.put("results",List.of(step));detail.put("small_game_type",round.mode()==GameRuleCore.Mode.TREASURE_HUNT?3:0);detail.put("total_win",total);detail.put("type",round.mode()==GameRuleCore.Mode.TREASURE_HUNT?2:1);detail.put("extend",Map.of("act_bet_gold",0,"act_id","0","act_type",0,"mode",round.mode().name(),"rules_hash",GameRuleCore.RULES_HASH));return new Prepared(detail,betGold,total);}
    static Map<String,Object>finish(Prepared prepared,StateStore.Applied applied){Map<String,Object>d=new LinkedHashMap<>(prepared.detail());d.put("change_gold",applied.change());d.put("end_gold",applied.end());d.put("oid",applied.oid());d.put("start_gold",applied.start());return d;}
    static List<Integer>ints(int[]a){List<Integer>r=new ArrayList<>(a.length);for(int v:a)r.add(v);return r;}record Prepared(Map<String,Object>detail,BigDecimal betCost,BigDecimal totalWin){}
}
